// World setup for TodoMVC testing using happy-dom
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

function createWindow() {
  const html = fs.readFileSync(path.resolve(__dirname, '../../index.html'), 'utf8');
  const win = new Window({ url: 'http://localhost/' });
  win.document.documentElement.innerHTML = html;
  win.location.hash = '';

  // Load todomvc-common base.js
  const baseJs = fs.readFileSync(
    path.resolve(__dirname, '../../node_modules/todomvc-common/base.js'),
    'utf8'
  );
  win.eval(baseJs);

  // Load app.js
  const appJs = fs.readFileSync(
    path.resolve(__dirname, '../../js/app.js'),
    'utf8'
  );
  win.eval(appJs);

  return win;
}

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  setup() {
    this.window = createWindow();
    this.document = this.window.document;
    this.localStorage = this.window.localStorage;
    this.window.addEventListener('hashchange', () => {});
  }

  teardown() {
    if (this.localStorage) {
      this.localStorage.clear();
    }
    if (this.window) {
      this.window.close();
    }
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  query(selector) {
    return this.document.querySelector(selector);
  }

  queryAll(selector) {
    return this.document.querySelectorAll(selector);
  }

  todoItems() {
    return this.queryAll('.todo-list li');
  }

  findTodo(label) {
    const items = this.todoItems();
    for (const item of items) {
      const labelEl = item.querySelector('label');
      if (labelEl && labelEl.textContent.trim() === label) {
        return item;
      }
    }
    return null;
  }
}

module.exports = { TodoWorld };

// Hooks for TodoMVC testing
const { TodoWorld } = require('./world');
const { Before, After, setDefaultTimeout } = require('@cucumber/cucumber');

setDefaultTimeout(10000);

Before(function () {
  this.world = new TodoWorld();
  this.world.setup();
});

After(function () {
  if (this.world) {
    this.world.teardown();
  }
});

// Step definitions for TodoMVC scenarios
const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// ============================================================
// Background / Setup
// ============================================================

Given('the app is loaded', function () {
  // Already done in Before hook
});

// ============================================================
// Given: Setting up todos
// ============================================================

Given('the todo list contains {string}', function (title) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = title;
  const event = new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter',
    keyCode: 13,
    which: 13,
    bubbles: true
  });
  input.dispatchEvent(event);
});

Given('the todo list contains {string} and {string}', function (title1, title2) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = title2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('the todo list contains {string} completed and {string} active', function (completed, active) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = completed;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = active;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  // Toggle completed todo
  const items = this.world.todoItems();
  const cb = items[0].querySelector('.toggle');
  if (cb) cb.click();
});

Given('the todo list contains {string} and {string} both active', function (title1, title2) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = title2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('the todo list contains {string} active and {string} active and {string} completed', function (active1, active2, completed) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = active1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = active2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = completed;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const items = this.world.todoItems();
  const cb = items[2].querySelector('.toggle');
  if (cb) cb.click();
});

Given('the todo list is empty', function () {
  this.world.setup();
});

Given('the new-todo input is focused', function () {
  const input = this.world.query('.new-todo');
  input.focus();
});

Given('{string} is marked as completed', function (title) {
  this.world.setup();
  const input = this.world.query('.new-todo');
  input.value = title;
