// Step definitions for TodoMVC scenarios
const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

// ============================================================
// Given: Setup
// ============================================================

Given('the app is loaded', function () {
  // Already done in Before hook
});

Given('the todo list contains {string}', function (title) {
  const input = this.world.query('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('the todo list contains {string} and {string}', function (title1, title2) {
  const input = this.world.query('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = title2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('the todo list contains {string} completed and {string} active', function (completed, active) {
  const input = this.world.query('.new-todo');
  input.value = completed;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = active;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const items = this.world.todoItems();
  const cb = items[0].querySelector('.toggle');
  if (cb) cb.click();
});

Given('the todo list contains {string} and {string} both active', function (title1, title2) {
  const input = this.world.query('.new-todo');
  input.value = title1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = title2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('the todo list contains {string} active and {string} active and {string} completed', function (active1, active2, completed) {
  const input = this.world.query('.new-todo');
  input.value = active1;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = active2;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = completed;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const items = this.world.todoItems();
  const cb = items[2].querySelector('.toggle');
  if (cb) cb.click();
});

Given('the todo list is empty', function () {
  // Already empty from world setup
});

Given('the new-todo input is focused', function () {
  const input = this.world.query('.new-todo');
  input.focus();
});

Given('{string} is marked as completed', function (title) {
  const input = this.world.query('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const items = this.world.todoItems();
  for (const item of items) {
    const label = item.querySelector('label');
    if (label && label.textContent.trim() === title) {
      const cb = item.querySelector('.toggle');
      if (cb) cb.click();
      break;
    }
  }
});

Given('all todos are marked as completed', function () {
  const toggleAll = this.world.query('#toggle-all');
  if (toggleAll) toggleAll.click();
});

Given('I am editing {string}', function (title) {
  const input = this.world.query('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const item = this.world.findTodo(title);
  if (item) {
    const label = item.querySelector('label');
    if (label) {
      label.dispatchEvent(new this.world.window.MouseEvent('dblclick', {
        bubbles: true, cancelable: true
      }));
    }
  }
});

Given('I am editing {string} and have changed it to {string}', function (original, changed) {
  const input = this.world.query('.new-todo');
  input.value = original;
  input.dispatchEvent(new this.world.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  const item = this.world.findTodo(original);
  if (item) {
    const label = item.querySelector('label');
    if (label) {
      label.dispatchEvent(new this.world.window.MouseEvent('dblclick', {
        bubbles: true, cancelable: true
      }));
    }
    const editInput = item.querySelector('.edit');
    if (editInput) {
      editInput.value = changed;
    }
  }
});

Given('the URL hash is {string}', function (hash) {
  this.world.window.location.hash = hash;
});

// ============================================================
// When: Actions
