        key: 'Escape', keyCode: 27, which: 27, bubbles: true
      }));
    }
  }
});

When('the page is reloaded', function () {
  // Persist current localStorage to rehydrate after "reload"
  const snapshot = {};
  for (let i = 0; i < this.world.localStorage.length; i++) {
    const key = this.world.localStorage.key(i);
    snapshot[key] = this.world.localStorage.getItem(key);
