Then('each stored todo has an id, a title, and a completed property', function () {
  const keys = Object.keys(this.world.localStorage);
  const todosKey = keys.find(k => k.startsWith('todos-'));
  assert.ok(todosKey, 'Expected a todos-* key in localStorage');
  const data = JSON.parse(this.world.localStorage.getItem(todosKey));
  assert.ok(Array.isArray(data), 'Expected todo data to be an array');
  for (const todo of data) {
    assert.ok(todo.hasOwnProperty('id'), 'Expected todo to have id');
    assert.ok(todo.hasOwnProperty('title'), 'Expected todo to have title');
    assert.ok(todo.hasOwnProperty('completed'), 'Expected todo to have completed');
  }
});

Then('no todo is in editing mode', function () {
  const keys = Object.keys(this.world.localStorage);
  const todosKey = keys.find(k => k.startsWith('todos-'));
  if (todosKey) {
    const data = JSON.parse(this.world.localStorage.getItem(todosKey));
    for (const todo of data) {
      assert.ok(!todo.hasOwnProperty('editing') || !todo.editing, 'Expected no todo to be in editing mode');
    }
  }
});

Then('both {string} and {string} are displayed', function (title1, title2) {
  const items = this.world.todoItems();
  const labels = Array.from(items).map(li => li.querySelector('label').textContent.trim());
  assert.ok(labels.includes(title1), `Expected "${title1}" to be displayed`);
  assert.ok(labels.includes(title2), `Expected "${title2}" to be displayed`);
  // All items should be visible
  for (const item of items) {
    const style = this.world.window.getComputedStyle(item);
    assert.notStrictEqual(style.display, 'none', 'Expected all items to be visible');
  }
});

Then('only {string} is displayed', function (title) {
  const items = this.world.todoItems();
  let visibleCount = 0;
  for (const item of items) {
    const style = this.world.window.getComputedStyle(item);
    if (style.display !== 'none') {
      visibleCount++;
      const label = item.querySelector('label').textContent.trim();
      assert.strictEqual(label, title, `Expected only "${title}" to be visible`);
    }
  }
  assert.strictEqual(visibleCount, 1, `Expected exactly 1 visible item`);
});

Then('{string} is hidden', function (title) {
  const item = this.world.findTodo(title);
  if (item) {
    const style = this.world.window.getComputedStyle(item);
    assert.strictEqual(style.display, 'none', `Expected "${title}" to be hidden`);
  }
});

Then('{string} is hidden from the active view', function (title) {
  const item = this.world.findTodo(title);
  if (item) {
    const style = this.world.window.getComputedStyle(item);
    assert.strictEqual(style.display, 'none', `Expected "${title}" to be hidden from active view`);
  }
});

Then('the {string} filter link has the selected class', function (filterName) {
  const filters = this.world.queryAll('.filters a');
  let found = false;
  for (const a of filters) {
    if (a.textContent.trim() === filterName) {
      assert.ok(a.classList.contains('selected'), `Expected "${filterName}" filter link to have selected class`);
      found = true;
    } else {
      assert.ok(!a.classList.contains('selected'), `Expected "${a.textContent.trim()}" filter link to NOT have selected class`);
    }
  }
  assert.ok(found, `Expected "${filterName}" filter link to exist`);
});

Then('the URL hash remains {string}', function (hash) {
  assert.strictEqual(this.world.window.location.hash, hash);
});

Then('the todo-count shows {string}', function (count) {
  const countEl = this.world.query('.todo-count');
  assert.ok(countEl, 'Expected .todo-count element');
  const strong = countEl.querySelector('strong');
  assert.ok(strong, 'Expected strong tag inside todo-count');
  assert.strictEqual(strong.textContent.trim(), count, `Expected todo-count to show "${count}"`);
});

Then('the count is wrapped in a <strong> tag', function () {
  const strong = this.world.query('.todo-count strong');
  assert.ok(strong, 'Expected a <strong> tag inside .todo-count');
  assert.strictEqual(strong.parentElement.className, 'todo-count');
});

Then('the todo-count reads {string}', function (text) {
  const countEl = this.world.query('.todo-count');
  assert.ok(countEl, 'Expected .todo-count element');
  assert.strictEqual(countEl.textContent.trim().replace(/\s+/g, ' '), text);
});

