  this.world.window.location.hash = hash;
  this.world.window.dispatchEvent(new this.world.window.Event('load'));
  this.world.window.dispatchEvent(new this.world.window.HashChangeEvent('hashchange', {
    oldURL: 'http://localhost/',
    newURL: 'http://localhost/' + hash
  }));
});

