+ */

 var ENTER_KEY = 13;
 var ESCAPE_KEY = 27;

 (function () {
   'use strict';
+
+  var STORAGE_KEY = 'todos-vanilla';
+
+  var todoApp = document.querySelector('.todoapp');
+  var newTodo = document.querySelector('.new-todo');
+  var todoList = document.querySelector('.todo-list');
+  var main = document.querySelector('.main');
+  var footer = document.querySelector('.footer');
+  var toggleAll = document.querySelector('#toggle-all');
+  var todoCount = document.querySelector('.todo-count');
+  var clearCompleted = document.querySelector('.clear-completed');
+  var filters = document.querySelectorAll('.filters a');
+
+  var todos = [];
+  var nowShowing = 'all';
+
+  // Load from localStorage
+  function load() {
+    var stored = localStorage.getItem(STORAGE_KEY);
+    if (stored) {
+      try {
+        todos = JSON.parse(stored);
+      } catch (e) {
+        todos = [];
+      }
+    }
+  }
+
+  function save() {
+    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
+  }
+
+  function generateId() {
+    return Date.now() + Math.random();
+  }
+
+  // Render
+  function render() {
+    var filtered = todos.filter(function (todo) {
+      if (nowShowing === 'active') return !todo.completed;
+      if (nowShowing === 'completed') return todo.completed;
+      return true;
+    });
+
+    todoList.innerHTML = '';
+    filtered.forEach(function (todo) {
+      var li = document.createElement('li');
+      if (todo.completed) li.classList.add('completed');
+
+      var viewDiv = document.createElement('div');
+      viewDiv.classList.add('view');
+
+      var checkbox = document.createElement('input');
+      checkbox.classList.add('toggle');
+      checkbox.type = 'checkbox';
+      checkbox.checked = todo.completed;
+
+      var label = document.createElement('label');
+      label.textContent = todo.title;
+
+      var destroyBtn = document.createElement('button');
+      destroyBtn.classList.add('destroy');
+
+      viewDiv.appendChild(checkbox);
+      viewDiv.appendChild(label);
+      viewDiv.appendChild(destroyBtn);
+
+      var editInput = document.createElement('input');
+      editInput.classList.add('edit');
+      editInput.value = todo.title;
+
+      li.appendChild(viewDiv);
+      li.appendChild(editInput);
+
+      li._todoId = todo.id;
+
+      // Toggle
+      checkbox.addEventListener('change', function () {
+        todo.completed = checkbox.checked;
+        if (todo.completed) {
+          li.classList.add('completed');
+        } else {
+          li.classList.remove('completed');
+        }
+        save();
+        render();
+      });
+
+      // Destroy
+      destroyBtn.addEventListener('click', function () {
+        todos = todos.filter(function (t) { return t.id !== todo.id; });
+        save();
+        render();
+      });
+
+      // Edit
+      label.addEventListener('dblclick', function () {
+        li.classList.add('editing');
+        editInput.focus();
+        editInput.value = todo.title;
+      });
+
+      editInput.addEventListener('keydown', function (e) {
+        if (e.keyCode === ENTER_KEY) {
+          e.preventDefault();
+          finishEdit(li, todo, editInput);
+        } else if (e.keyCode === ESCAPE_KEY) {
+          li.classList.remove('editing');
+          editInput.value = todo.title;
+        }
+      });
+
+      editInput.addEventListener('blur', function () {
+        finishEdit(li, todo, editInput);
+      });
+
+      todoList.appendChild(li);
+    });
+
+    // Show/hide main and footer
+    var hasTodos = todos.length > 0;
+    main.style.display = hasTodos ? 'block' : 'none';
+    footer.style.display = hasTodos ? 'block' : 'none';
+
+    // Toggle-all state
+    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
+    var completedCount = todos.length - activeCount;
+    toggleAll.checked = todos.length > 0 && activeCount === 0;
+
+    // Counter
+    var count = activeCount;
+    var word = count === 1 ? 'item' : 'items';
+    todoCount.innerHTML = '<strong>' + count + '</strong> ' + word + ' left';
+
+    // Clear-completed
+    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';
+
+    // Filter links
+    filters.forEach(function (a) {
+      a.classList.remove('selected');
+      if (a.hash === '#/' && nowShowing === 'all') a.classList.add('selected');
+      else if (a.hash === '#/active' && nowShowing === 'active') a.classList.add('selected');
+      else if (a.hash === '#/completed' && nowShowing === 'completed') a.classList.add('selected');
+    });
+  }
+
+  function finishEdit(li, todo, editInput) {
+    var val = editInput.value.trim();
+    if (val) {
+      todo.title = val;
+      li.classList.remove('editing');
+      save();
+      render();
+    } else {
+      todos = todos.filter(function (t) { return t.id !== todo.id; });
+      save();
+      render();
+    }
+  }
+
+  // New todo creation
+  newTodo.addEventListener('keydown', function (e) {
+    if (e.keyCode === ENTER_KEY) {
+      e.preventDefault();
+      var val = newTodo.value.trim();
+      if (val) {
+        todos.push({
+          id: generateId(),
+          title: val,
+          completed: false
+        });
+        newTodo.value = '';
+        save();
+        render();
+      } else {
+        // Ignore empty
+        save();
+        render();
+      }
+    }
+  });
+
+  // Toggle-all
+  toggleAll.addEventListener('change', function () {
+    var checked = toggleAll.checked;
+    todos.forEach(function (todo) {
+      todo.completed = checked;
+    });
+    save();
+    render();
+  });
+
+  // Clear completed
+  clearCompleted.addEventListener('click', function () {
+    todos = todos.filter(function (t) { return !t.completed; });
+    save();
+    render();
+  });
+
+  // Routing
+  function handleHash() {
+    var hash = window.location.hash;
+    if (hash === '#/active') nowShowing = 'active';
+    else if (hash === '#/completed') nowShowing = 'completed';
+    else nowShowing = 'all';
+    render();
+  }
+
+  window.addEventListener('hashchange', handleHash);
+  window.addEventListener('load', function () {
+    load();
+    handleHash();
+  });
+
+  // Initial render
+  load();
+  handleHash();
 })();
